// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Split Report Attachments
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Fans each IMAP email out into one item per DMARC-looking attachment (.zip, .gz or raw .xml)
// and renames the binary key to `report`, so every downstream node is attachment-agnostic.
// Emails without a DMARC-looking attachment produce no items and stop here.

const items = $input.all();
const out = [];

function classify(fileName, mimeType) {
  const name = String(fileName || '').toLowerCase();
  const mime = String(mimeType || '').toLowerCase();
  if (name.endsWith('.gz') || name.endsWith('.gzip') || mime.includes('gzip')) return 'gz';
  if (name.endsWith('.zip') || mime.includes('zip')) return 'zip';
  if (name.endsWith('.xml') || mime.includes('xml')) return 'xml';
  return null;
}

function fromAddress(from) {
  if (!from) return null;
  if (typeof from === 'string') return from;
  if (from.text) return from.text;
  if (Array.isArray(from.value) && from.value[0]) return from.value[0].address || null;
  return null;
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const email = item.json || {};
  const binaries = item.binary || {};

  for (const [key, bin] of Object.entries(binaries)) {
    const kind = classify(bin.fileName, bin.mimeType);
    if (!kind) continue;

    out.push({
      json: {
        kind,
        source: 'imap',
        file_name: bin.fileName || key,
        mime_type: bin.mimeType || null,
        email_subject: email.subject || null,
        email_from: fromAddress(email.from),
        email_date: email.date || null,
        message_id: email.messageId || email['message-id'] || null,
      },
      // fileExtension is forced so the Compression node reliably picks zip vs gzip.
      binary: { report: { ...bin, fileExtension: kind } },
      pairedItem: { item: i },
    });
  }
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Extract & Validate XML
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Reads every binary on each item (raw `report` or decompressed `xml_*`), converts it to UTF-8 text
// and applies safety gates before parsing:
//   - size cap (MAX_XML_BYTES), protects the instance from oversized or zip-bomb payloads
//   - DOCTYPE / ENTITY rejection, no legitimate DMARC report needs them (blocks XXE / entity expansion)
//   - must contain a <feedback> root, otherwise it is not an aggregate report
// Items that fail a gate are emitted with ok=false and routed to the parse-failure branch.

function env(name, fallback) {
  try {
    const v = $env[name];
    return v === undefined || v === null || v === '' ? fallback : String(v);
  } catch (e) {
    return fallback;
  }
}

const MAX_XML_BYTES = Number(env('MAX_XML_BYTES', '26214400')) || 26214400;
const items = $input.all();
const out = [];

function fail(meta, i, reason, detail, fileName) {
  return {
    json: { ...meta, file_name: fileName || meta.file_name || null, ok: false, reason, error_message: detail || null },
    pairedItem: { item: i },
  };
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const meta = { ...(item.json || {}) };
  delete meta.kind;
  const keys = Object.keys(item.binary || {});

  if (!keys.length) {
    out.push(fail(meta, i, 'no_binary_after_decompression', 'Archive was empty or contained no readable file'));
    continue;
  }

  for (const key of keys) {
    const bin = item.binary[key];
    const fileName = (bin && bin.fileName) || meta.file_name || key;

    let buf;
    try {
      buf = await this.helpers.getBinaryDataBuffer(i, key);
    } catch (e) {
      out.push(fail(meta, i, 'binary_read_error', e.message, fileName));
      continue;
    }

    if (buf.length > MAX_XML_BYTES) {
      out.push(fail(meta, i, 'xml_too_large', `${buf.length} bytes exceeds MAX_XML_BYTES=${MAX_XML_BYTES}`, fileName));
      continue;
    }

    const xml = buf.toString('utf8').replace(/^﻿/, '').trim();

    if (/<!DOCTYPE|<!ENTITY/i.test(xml)) {
      out.push(fail(meta, i, 'doctype_or_entity_rejected', 'DOCTYPE/ENTITY declarations are not allowed in DMARC reports', fileName));
      continue;
    }
    if (!/<feedback[\s>]/i.test(xml)) {
      out.push(fail(meta, i, 'not_a_dmarc_aggregate_report', 'No <feedback> root element found', fileName));
      continue;
    }

    out.push({
      json: { ...meta, file_name: fileName, ok: true, xml, xml_bytes: buf.length },
      pairedItem: { item: i },
    });
  }
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Compute Alignment & Detect Spoofing
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Input : one item per parsed DMARC aggregate report (output of the XML node, explicitArray=false).
// Output: one `dmarc_report` event per report with per-IP SPF/DKIM alignment rates, sender
//         classification, spoofing sources, a health score and alert decision. Structurally broken
//         reports become `parse_failure` events instead.
//
// Alignment verdicts come from the reporter's <policy_evaluated> block (the receiver's own DMARC
// evaluation). Raw <auth_results> are reported alongside so you can see "authenticated but not aligned" gaps.

const SCHEMA_VERSION = '1.0';

function env(name, fallback) {
  try {
    const v = $env[name];
    return v === undefined || v === null || v === '' ? fallback : String(v);
  } catch (e) {
    return fallback;
  }
}
const list = (s) => String(s || '').split(/[\s,;]+/).map((x) => x.trim()).filter(Boolean);
const num = (s, d) => (Number.isFinite(Number(s)) ? Number(s) : d);
const bool = (s, d) => (s === undefined || s === null || s === '' ? d : ['1', 'true', 'yes', 'on'].includes(String(s).toLowerCase()));
const toArray = (v) => (v === undefined || v === null || v === '' ? [] : Array.isArray(v) ? v : [v]);
const txt = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'object') return v._ !== undefined ? String(v._).trim() : '';
  return String(v).trim();
};
const pct = (n, d) => (d > 0 ? Math.round((n / d) * 10000) / 100 : null);
const lowerDomain = (d) => txt(d).toLowerCase().replace(/\.$/, '');

// ---------- IP / CIDR matching (IPv4 + IPv6, BigInt based) ----------
function parseIPv4(ip) {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  let n = 0n;
  for (const p of parts) {
    if (!/^\d{1,3}$/.test(p) || Number(p) > 255) return null;
    n = (n << 8n) + BigInt(Number(p));
  }
  return { v: n, bits: 32 };
}
function parseIPv6(ip) {
  ip = ip.split('%')[0].toLowerCase();
  const embedded = ip.match(/^(.*:)(\d{1,3}(?:\.\d{1,3}){3})$/);
  if (embedded) {
    const v4 = parseIPv4(embedded[2]);
    if (!v4) return null;
    ip = embedded[1] + ((v4.v >> 16n) & 0xffffn).toString(16) + ':' + (v4.v & 0xffffn).toString(16);
  }
  const halves = ip.split('::');
  if (halves.length > 2) return null;
  const groupsOf = (s) => (s === '' ? [] : s.split(':'));
  let groups;
  if (halves.length === 2) {
    const left = groupsOf(halves[0]);
    const right = groupsOf(halves[1]);
    const fill = 8 - left.length - right.length;
    if (fill < 1) return null;
    groups = [...left, ...Array(fill).fill('0'), ...right];
  } else {
    groups = groupsOf(halves[0]);
  }
  if (groups.length !== 8) return null;
  let n = 0n;
  for (const g of groups) {
    if (!/^[0-9a-f]{1,4}$/.test(g)) return null;
    n = (n << 16n) + BigInt(parseInt(g, 16));
  }
  return { v: n, bits: 128 };
}
function parseIP(ip) {
  ip = String(ip || '').trim();
  if (!ip) return null;
  const parsed = ip.includes(':') ? parseIPv6(ip) : parseIPv4(ip);
  // Normalise IPv4-mapped IPv6 (::ffff:a.b.c.d) to plain IPv4.
  if (parsed && parsed.bits === 128 && parsed.v >> 32n === 0xffffn) return { v: parsed.v & 0xffffffffn, bits: 32 };
  return parsed;
}
function parseCidr(entry) {
  const [base, len] = entry.split('/');
  const ip = parseIP(base);
  if (!ip) return null;
  const prefix = len === undefined ? ip.bits : Number(len);
  if (!Number.isInteger(prefix) || prefix < 0 || prefix > ip.bits) return null;
  const shift = BigInt(ip.bits - prefix);
  return { entry, bits: ip.bits, shift, net: ip.v >> shift };
}

// ---------- Configuration ----------
const configWarnings = [];
const CFG = {
  sandbox: bool(env('SANDBOX_MODE', 'true'), true),
  watchlist: list(env('DOMAIN_WATCHLIST', '')).map(lowerDomain),
  spoofMin: Math.max(1, num(env('SPOOF_MIN_MESSAGES', '5'), 5)),
  warn: num(env('HEALTH_WARN_THRESHOLD', '98'), 98),
  crit: num(env('HEALTH_CRITICAL_THRESHOLD', '90'), 90),
  alertOnSpoofing: bool(env('ALERT_ON_SPOOFING', 'true'), true),
  alertOnWarning: bool(env('ALERT_ON_WARNING', 'false'), false),
  alertOnParseFailure: bool(env('ALERT_ON_PARSE_FAILURE', 'true'), true),
  allowlist: [],
};
for (const entry of list(env('AUTHORIZED_SENDER_IPS', ''))) {
  const c = parseCidr(entry);
  if (c) CFG.allowlist.push(c);
  else configWarnings.push(`Ignored invalid AUTHORIZED_SENDER_IPS entry: ${entry}`);
}
if (CFG.crit > CFG.warn) configWarnings.push('HEALTH_CRITICAL_THRESHOLD is above HEALTH_WARN_THRESHOLD; check thresholds');

function ipAuthorized(ip) {
  if (!CFG.allowlist.length) return null; // unknown: no allowlist configured
  const p = parseIP(ip);
  if (!p) return false;
  return CFG.allowlist.some((c) => c.bits === p.bits && p.v >> c.shift === c.net);
}

const FORWARDING_REASONS = new Set(['forwarded', 'mailing_list', 'trusted_forwarder']);
const EXCLUDED_FROM_HEALTH = new Set(['unauthorized_spoofing', 'unauthorized_low_volume', 'probable_forwarder']);
const SEVERITY = {
  authorized_aligned: 'ok',
  aligned_sender: 'ok',
  unlisted_aligned_sender: 'info',
  probable_forwarder: 'info',
  authorized_misaligned: 'warning',
  unlisted_partially_aligned: 'warning',
  unauthorized_low_volume: 'warning',
  unauthorized_spoofing: 'critical',
};

function toIso(epoch) {
  const n = Number(epoch);
  return Number.isFinite(n) && n > 0 ? new Date(n * 1000).toISOString() : null;
}

function upstreamMeta(i) {
  try {
    const m = $('XML Extracted?').itemMatching(i);
    const x = (m && m.json) || {};
    return {
      source: x.source || null,
      file_name: x.file_name || null,
      email_subject: x.email_subject || null,
      email_from: x.email_from || null,
      message_id: x.message_id || null,
    };
  } catch (e) {
    return { source: null, file_name: null, email_subject: null, email_from: null, message_id: null };
  }
}

function parseFailureEvent(meta, reason, detail, processedAt) {
  const alert = CFG.alertOnParseFailure;
  return {
    event_type: 'parse_failure',
    schema_version: SCHEMA_VERSION,
    report_key: `parse_failure|${meta.file_name || 'unknown'}|${processedAt}`,
    sandbox_mode: CFG.sandbox,
    processed_at: processedAt,
    ...meta,
    reason,
    error_message: detail || null,
    health: { status: 'unknown' },
    alert_required: alert,
    alert_reasons: alert ? [`Report could not be parsed: ${reason}`] : [],
    dashboard_row: {
      report_key: `parse_failure|${meta.file_name || 'unknown'}|${processedAt}`,
      event_type: 'parse_failure',
      file_name: meta.file_name || null,
      reason,
      health_status: 'unknown',
      alert_required: alert,
      processed_at: processedAt,
    },
  };
}

function newAgg(ip) {
  return {
    source_ip: ip,
    messages: 0,
    dkim_aligned_pass: 0,
    spf_aligned_pass: 0,
    dmarc_pass: 0,
    dmarc_fail: 0,
    forwarding_fail: 0,
    dkim_auth_pass: 0,
    spf_auth_pass: 0,
    dispositions: {},
    header_from: new Set(),
    envelope_from: new Set(),
    dkim_domains: new Set(),
    spf_domains: new Set(),
    override_reasons: new Set(),
  };
}

// ---------- Main ----------
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const processedAt = new Date().toISOString();
  const j = items[i].json || {};
  const meta = upstreamMeta(i);
  const fb = j.feedback || (j.report_metadata ? j : null);

  if (!fb || typeof fb !== 'object' || !fb.report_metadata || !fb.policy_published) {
    out.push({ json: parseFailureEvent(meta, 'missing_required_dmarc_sections', 'report_metadata or policy_published not found', processedAt), pairedItem: { item: i } });
    continue;
  }

  const rm = fb.report_metadata;
  const pp = fb.policy_published;
  const orgName = txt(rm.org_name) || 'unknown_reporter';
  const reportId = txt(rm.report_id) || `no_id_${processedAt}`;
  const domain = lowerDomain(pp.domain);
  const pctRaw = txt(pp.pct);
  const policy = {
    p: txt(pp.p).toLowerCase() || null,
    sp: txt(pp.sp).toLowerCase() || null,
    np: txt(pp.np).toLowerCase() || null,
    pct: pctRaw === '' ? 100 : num(pctRaw, 100),
    adkim: txt(pp.adkim).toLowerCase() || 'r',
    aspf: txt(pp.aspf).toLowerCase() || 'r',
    fo: txt(pp.fo) || null,
  };

  const byIp = new Map();
  let malformedRecords = 0;

  for (const rec of toArray(fb.record)) {
    const row = (rec && rec.row) || {};
    const pe = row.policy_evaluated || {};
    const ip = txt(row.source_ip);
    if (!ip || !parseIP(ip)) {
      malformedRecords++;
      continue;
    }
    const count = Math.max(0, parseInt(txt(row.count), 10) || 0);
    const dkimAligned = txt(pe.dkim).toLowerCase() === 'pass';
    const spfAligned = txt(pe.spf).toLowerCase() === 'pass';
    const dmarcPass = dkimAligned || spfAligned;
    const disposition = txt(pe.disposition).toLowerCase() || 'none';
    const reasons = toArray(pe.reason).map((r) => txt(r && r.type).toLowerCase()).filter(Boolean);
    const ids = rec.identifiers || {};
    const ar = rec.auth_results || {};
    const dkimResults = toArray(ar.dkim);
    const spfResults = toArray(ar.spf);

    const agg = byIp.get(ip) || newAgg(ip);
    agg.messages += count;
    if (dkimAligned) agg.dkim_aligned_pass += count;
    if (spfAligned) agg.spf_aligned_pass += count;
    if (dmarcPass) agg.dmarc_pass += count;
    else {
      agg.dmarc_fail += count;
      if (reasons.some((r) => FORWARDING_REASONS.has(r))) agg.forwarding_fail += count;
    }
    if (dkimResults.some((d) => txt(d && d.result).toLowerCase() === 'pass')) agg.dkim_auth_pass += count;
    if (spfResults.some((s) => txt(s && s.result).toLowerCase() === 'pass')) agg.spf_auth_pass += count;
    agg.dispositions[disposition] = (agg.dispositions[disposition] || 0) + count;

    const hf = lowerDomain(ids.header_from);
    const ef = lowerDomain(ids.envelope_from);
    if (hf) agg.header_from.add(hf);
    if (ef) agg.envelope_from.add(ef);
    for (const d of dkimResults) {
      const dd = lowerDomain(d && d.domain);
      if (dd) agg.dkim_domains.add(`${dd}${txt(d.selector) ? ` (s=${txt(d.selector)})` : ''}: ${txt(d.result).toLowerCase() || 'unknown'}`);
    }
    for (const s of spfResults) {
      const sd = lowerDomain(s && s.domain);
      if (sd) agg.spf_domains.add(`${sd}: ${txt(s.result).toLowerCase() || 'unknown'}`);
    }
    for (const r of reasons) agg.override_reasons.add(r);
    byIp.set(ip, agg);
  }

  // ---------- Classification ----------
  const perIp = [];
  const classificationCounts = {};
  const totals = { messages: 0, unique_ips: 0, dkim_aligned_pass: 0, spf_aligned_pass: 0, dmarc_pass: 0, dmarc_fail: 0, dkim_auth_pass: 0, spf_auth_pass: 0, dispositions: {} };
  let legitMessages = 0;
  let legitPass = 0;

  for (const agg of byIp.values()) {
    if (agg.messages === 0) continue;
    const authorized = ipAuthorized(agg.source_ip);
    let classification;
    if (agg.dmarc_fail === 0) classification = authorized === false ? 'unlisted_aligned_sender' : authorized === true ? 'authorized_aligned' : 'aligned_sender';
    else if (authorized === true) classification = 'authorized_misaligned';
    else if (agg.forwarding_fail === agg.dmarc_fail) classification = 'probable_forwarder';
    else if (agg.dmarc_pass > 0) classification = 'unlisted_partially_aligned';
    else if (agg.dmarc_fail - agg.forwarding_fail >= CFG.spoofMin) classification = 'unauthorized_spoofing';
    else classification = 'unauthorized_low_volume';

    classificationCounts[classification] = (classificationCounts[classification] || 0) + 1;
    if (!EXCLUDED_FROM_HEALTH.has(classification)) {
      legitMessages += agg.messages;
      legitPass += agg.dmarc_pass;
    }

    totals.messages += agg.messages;
    totals.unique_ips += 1;
    for (const k of ['dkim_aligned_pass', 'spf_aligned_pass', 'dmarc_pass', 'dmarc_fail', 'dkim_auth_pass', 'spf_auth_pass']) totals[k] += agg[k];
    for (const [d, c] of Object.entries(agg.dispositions)) totals.dispositions[d] = (totals.dispositions[d] || 0) + c;

    perIp.push({
      source_ip: agg.source_ip,
      ip_version: agg.source_ip.includes(':') ? 6 : 4,
      authorized,
      classification,
      severity: SEVERITY[classification],
      messages: agg.messages,
      dkim_aligned_pass: agg.dkim_aligned_pass,
      spf_aligned_pass: agg.spf_aligned_pass,
      dmarc_pass: agg.dmarc_pass,
      dmarc_fail: agg.dmarc_fail,
      dkim_aligned_rate: pct(agg.dkim_aligned_pass, agg.messages),
      spf_aligned_rate: pct(agg.spf_aligned_pass, agg.messages),
      dmarc_pass_rate: pct(agg.dmarc_pass, agg.messages),
      dkim_auth_rate: pct(agg.dkim_auth_pass, agg.messages),
      spf_auth_rate: pct(agg.spf_auth_pass, agg.messages),
      dispositions: agg.dispositions,
      header_from: [...agg.header_from],
      envelope_from: [...agg.envelope_from],
      dkim_results: [...agg.dkim_domains],
      spf_results: [...agg.spf_domains],
      override_reasons: [...agg.override_reasons],
    });
  }
  perIp.sort((a, b) => b.messages - a.messages || a.source_ip.localeCompare(b.source_ip));

  const spoofSources = perIp.filter((p) => p.classification === 'unauthorized_spoofing');
  const spoofMessages = spoofSources.reduce((s, p) => s + p.messages, 0);
  const ipsOf = (cls) => perIp.filter((p) => p.classification === cls).map((p) => p.source_ip);

  // ---------- Health ----------
  const healthScore = pct(legitPass, legitMessages);
  let healthStatus;
  if (legitMessages === 0) healthStatus = 'no_legitimate_traffic';
  else if (healthScore >= CFG.warn) healthStatus = 'healthy';
  else if (healthScore >= CFG.crit) healthStatus = 'warning';
  else healthStatus = 'critical';

  // ---------- Recommendations ----------
  const recommendations = [];
  if (policy.p === 'none') recommendations.push('Policy is p=none (monitor only): spoofed mail is still delivered. Once all legitimate sources align, move to p=quarantine, then p=reject.');
  if (policy.pct < 100) recommendations.push(`Policy applies to pct=${policy.pct}% of failing mail; raise to 100 once stable.`);
  if (!CFG.allowlist.length) recommendations.push('AUTHORIZED_SENDER_IPS is empty: sender classification relies on DMARC results only. Configure your known sending IPs/CIDRs.');
  if (ipsOf('authorized_misaligned').length) recommendations.push(`Fix DKIM signing and/or SPF alignment on authorized senders: ${ipsOf('authorized_misaligned').join(', ')}`);
  if (ipsOf('unlisted_aligned_sender').length) recommendations.push(`These IPs pass DMARC but are not on your allowlist. Verify the vendor and add them if legitimate: ${ipsOf('unlisted_aligned_sender').join(', ')}`);
  if (ipsOf('unlisted_partially_aligned').length) recommendations.push(`Investigate partially aligned, unlisted senders: ${ipsOf('unlisted_partially_aligned').join(', ')}`);
  if (spoofSources.length && policy.p === 'none') recommendations.push('Spoofing detected while p=none: those messages were delivered. Prioritise enforcement.');

  // ---------- Scope & alerting ----------
  const inScope = !CFG.watchlist.length || CFG.watchlist.includes(domain);
  const alertReasons = [];
  if (inScope) {
    if (spoofSources.length && CFG.alertOnSpoofing) alertReasons.push(`${spoofSources.length} unauthorized spoofing source(s), ${spoofMessages} message(s)`);
    if (healthStatus === 'critical') alertReasons.push(`Health score ${healthScore}% is below critical threshold ${CFG.crit}%`);
    if (healthStatus === 'warning' && CFG.alertOnWarning) alertReasons.push(`Health score ${healthScore}% is below warning threshold ${CFG.warn}%`);
  }

  const reportKey = `${orgName}|${reportId}`;
  const dateRange = { begin: toIso(txt(rm.date_range && rm.date_range.begin)), end: toIso(txt(rm.date_range && rm.date_range.end)) };
  const rates = {
    dkim_aligned: pct(totals.dkim_aligned_pass, totals.messages),
    spf_aligned: pct(totals.spf_aligned_pass, totals.messages),
    dmarc_pass: pct(totals.dmarc_pass, totals.messages),
    dkim_auth: pct(totals.dkim_auth_pass, totals.messages),
    spf_auth: pct(totals.spf_auth_pass, totals.messages),
  };

  out.push({
    json: {
      event_type: 'dmarc_report',
      schema_version: SCHEMA_VERSION,
      report_key: reportKey,
      in_scope: inScope,
      sandbox_mode: CFG.sandbox,
      processed_at: processedAt,
      ...meta,
      reporter: { org_name: orgName, email: txt(rm.email) || null, extra_contact_info: txt(rm.extra_contact_info) || null, report_id: reportId },
      date_range: dateRange,
      policy_domain: domain,
      policy,
      totals,
      rates,
      health: { score: healthScore, status: healthStatus, legitimate_messages: legitMessages, legitimate_dmarc_pass: legitPass, warn_threshold: CFG.warn, critical_threshold: CFG.crit },
      spoofing: {
        source_count: spoofSources.length,
        message_count: spoofMessages,
        sources: spoofSources.map((p) => ({ source_ip: p.source_ip, messages: p.messages, dispositions: p.dispositions, header_from: p.header_from, envelope_from: p.envelope_from, spf_results: p.spf_results, dkim_results: p.dkim_results })),
      },
      classification_counts: classificationCounts,
      per_ip: perIp,
      recommendations,
      config_warnings: configWarnings,
      malformed_records: malformedRecords,
      alert_required: alertReasons.length > 0,
      alert_reasons: alertReasons,
      dashboard_row: {
        report_key: reportKey,
        event_type: 'dmarc_report',
        policy_domain: domain,
        in_scope: inScope,
        reporter_org: orgName,
        report_id: reportId,
        date_begin: dateRange.begin,
        date_end: dateRange.end,
        messages: totals.messages,
        unique_ips: totals.unique_ips,
        dmarc_pass_rate: rates.dmarc_pass,
        dkim_aligned_rate: rates.dkim_aligned,
        spf_aligned_rate: rates.spf_aligned,
        health_score: healthScore,
        health_status: healthStatus,
        spoofing_sources: spoofSources.length,
        spoofing_messages: spoofMessages,
        policy_p: policy.p,
        policy_pct: policy.pct,
        alert_required: alertReasons.length > 0,
        processed_at: processedAt,
      },
    },
    pairedItem: { item: i },
  });
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Build Parse-Failure Event
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Collects every item that could not become a parsed report (decompression error, failed safety
// gate, malformed XML) and turns it into a uniform `parse_failure` event, so failures are logged to
// the dashboard and alerted instead of disappearing silently.

const SCHEMA_VERSION = '1.0';

function env(name, fallback) {
  try {
    const v = $env[name];
    return v === undefined || v === null || v === '' ? fallback : String(v);
  } catch (e) {
    return fallback;
  }
}
const bool = (s, d) => (s === undefined || s === null || s === '' ? d : ['1', 'true', 'yes', 'on'].includes(String(s).toLowerCase()));

const SANDBOX = bool(env('SANDBOX_MODE', 'true'), true);
const ALERT = bool(env('ALERT_ON_PARSE_FAILURE', 'true'), true);

function errorText(e) {
  if (!e) return null;
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e).slice(0, 500);
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const processedAt = new Date().toISOString();

  let reason = j.reason;
  if (!reason) reason = j.kind && j.kind !== 'xml' ? 'decompression_failed' : j.error ? 'xml_parse_error' : 'unknown_parse_failure';

  const fileName = j.file_name || null;
  const key = `parse_failure|${fileName || 'unknown'}|${processedAt}|${i}`;

  out.push({
    json: {
      event_type: 'parse_failure',
      schema_version: SCHEMA_VERSION,
      report_key: key,
      sandbox_mode: SANDBOX,
      processed_at: processedAt,
      source: j.source || null,
      file_name: fileName,
      email_subject: j.email_subject || null,
      email_from: j.email_from || null,
      message_id: j.message_id || null,
      reason,
      error_message: j.error_message || errorText(j.error),
      health: { status: 'unknown' },
      alert_required: ALERT,
      alert_reasons: ALERT ? [`Report could not be parsed: ${reason}`] : [],
      dashboard_row: {
        report_key: key,
        event_type: 'parse_failure',
        file_name: fileName,
        reason,
        health_status: 'unknown',
        alert_required: ALERT,
        processed_at: processedAt,
      },
    },
    pairedItem: { item: i },
  });
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Sandbox Preview (No Delivery)
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// SANDBOX_MODE=true terminates here. Nothing is posted to the dashboard or alert webhooks; each item
// shows what WOULD have been delivered so you can verify parsing, classification and alert logic.

return $input.all().map((item, i) => {
  const e = item.json || {};
  let summary;
  if (e.event_type === 'dmarc_report') {
    summary = `${e.policy_domain} | ${e.reporter && e.reporter.org_name} | ${e.totals.messages} msgs | DMARC pass ${e.rates.dmarc_pass}% | health ${e.health.status} (${e.health.score}%) | spoofing sources ${e.spoofing.source_count}`;
  } else {
    summary = `${e.event_type}: ${e.reason || 'n/a'} (${e.file_name || 'unknown file'})`;
  }
  return {
    json: {
      sandbox_preview: true,
      summary,
      would_post_to_dashboard: true,
      would_send_alert: !!e.alert_required,
      alert_reasons: e.alert_reasons || [],
      dashboard_payload: e,
    },
    pairedItem: { item: i },
  };
});

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Dashboard Delivery Failure
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Receives items from the dashboard HTTP node's error output (after its built-in retries are
// exhausted) and converts them into `delivery_failure` alert events.

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  let failedKey = null;
  try {
    const src = $('Skip Already-Processed Reports').itemMatching(i);
    failedKey = (src && src.json && src.json.report_key) || null;
  } catch (e) {
    failedKey = j.report_key || null;
  }
  const err = j.error;
  const message = typeof err === 'string' ? err : (err && (err.message || err.description)) || 'Unknown HTTP error';
  const processedAt = new Date().toISOString();

  out.push({
    json: {
      event_type: 'delivery_failure',
      schema_version: '1.0',
      report_key: `delivery_failure|${failedKey || 'unknown'}|${processedAt}`,
      target: 'dashboard_webhook',
      failed_report_key: failedKey,
      error_message: String(message).slice(0, 1000),
      sandbox_mode: false,
      processed_at: processedAt,
      alert_required: true,
      alert_reasons: ['Dashboard webhook delivery failed after retries; the report was NOT logged'],
    },
    pairedItem: { item: i },
  });
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Format Alert Message
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Builds the alert webhook body.
//   ALERT_PAYLOAD_FORMAT=slack   -> { text }                         (Slack / Mattermost / Rocket.Chat incoming webhooks)
//   ALERT_PAYLOAD_FORMAT=generic -> { text, event_type, report_key, event }  (your own endpoint)

function env(name, fallback) {
  try {
    const v = $env[name];
    return v === undefined || v === null || v === '' ? fallback : String(v);
  } catch (e) {
    return fallback;
  }
}

const FORMAT = env('ALERT_PAYLOAD_FORMAT', 'slack').toLowerCase();
const MAX_SOURCES = Math.max(1, Number(env('MAX_SPOOF_SOURCES_IN_ALERT', '10')) || 10);
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const n = (v) => (typeof v === 'number' ? v.toLocaleString('en-US') : 'n/a');
const p = (v) => (typeof v === 'number' ? `${v}%` : 'n/a');
const disp = (d) => Object.entries(d || {}).map(([k, v]) => `${k}=${v}`).join(', ') || 'n/a';

const out = [];

for (const item of $input.all()) {
  const e = item.json || {};
  const lines = [];

  if (e.event_type === 'dmarc_report') {
    lines.push(`[DMARC] ${String(e.health.status).toUpperCase()} | ${esc(e.policy_domain)} | report ${esc(e.reporter.report_id)} from ${esc(e.reporter.org_name)}`);
    lines.push(`Window: ${e.date_range.begin} to ${e.date_range.end}`);
    lines.push(`Messages: ${n(e.totals.messages)} | DMARC pass: ${p(e.rates.dmarc_pass)} | DKIM aligned: ${p(e.rates.dkim_aligned)} | SPF aligned: ${p(e.rates.spf_aligned)}`);
    lines.push(`Legitimate-traffic health score: ${p(e.health.score)} (warning below ${e.health.warn_threshold}%, critical below ${e.health.critical_threshold}%)`);
    if (e.spoofing.source_count > 0) {
      lines.push(`Unauthorized spoofing sources: ${e.spoofing.source_count} IP(s), ${n(e.spoofing.message_count)} message(s)`);
      for (const s of e.spoofing.sources.slice(0, MAX_SOURCES)) {
        lines.push(`  - ${esc(s.source_ip)}: ${n(s.messages)} msgs, header_from ${esc(s.header_from.join('/'))}, disposition ${esc(disp(s.dispositions))}`);
      }
      if (e.spoofing.source_count > MAX_SOURCES) lines.push(`  ...and ${e.spoofing.source_count - MAX_SOURCES} more (see dashboard)`);
    }
    lines.push(`Published policy: p=${esc(e.policy.p)} sp=${esc(e.policy.sp || e.policy.p)} pct=${e.policy.pct} adkim=${esc(e.policy.adkim)} aspf=${esc(e.policy.aspf)}`);
    lines.push(`Triggered by: ${esc(e.alert_reasons.join('; '))}`);
    if (e.recommendations && e.recommendations.length) {
      lines.push('Next steps:');
      for (const r of e.recommendations.slice(0, 3)) lines.push(`  - ${esc(r)}`);
    }
  } else if (e.event_type === 'parse_failure') {
    lines.push(`[DMARC] PARSE FAILURE | file ${esc(e.file_name || 'unknown')} | reason ${esc(e.reason)}`);
    if (e.error_message) lines.push(`Error: ${esc(String(e.error_message).slice(0, 300))}`);
    if (e.email_subject) lines.push(`Email subject: ${esc(e.email_subject)}`);
    lines.push('The report was not processed. Inspect the n8n execution and the source email.');
  } else if (e.event_type === 'delivery_failure') {
    lines.push(`[DMARC] DELIVERY FAILURE | ${esc(e.target)} | report ${esc(e.failed_report_key || 'unknown')}`);
    lines.push(`Error: ${esc(e.error_message)}`);
    lines.push('The report was parsed but not logged. Re-run the execution once the dashboard endpoint is reachable.');
  } else {
    lines.push(`[DMARC] ${esc(e.event_type || 'event')}: ${esc(JSON.stringify(e).slice(0, 500))}`);
  }

  const text = lines.join('\n');
  out.push({ json: FORMAT === 'generic' ? { text, event_type: e.event_type, report_key: e.report_key, event: e } : { text } });
}

return out;

// n8n-outbound-dns-dmarc-rua-xml-report-parser :: Format Workflow Error
// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
//
// Runs when n8n reports an unhandled failure (requires this workflow to be set as its own Error
// Workflow in Settings). Suppressed in SANDBOX_MODE and when no alert URL is configured.

function env(name, fallback) {
  try {
    const v = $env[name];
    return v === undefined || v === null || v === '' ? fallback : String(v);
  } catch (e) {
    return fallback;
  }
}
const sandbox = ['1', 'true', 'yes', 'on'].includes(env('SANDBOX_MODE', 'true').toLowerCase());
const url = env('ERROR_ALERT_WEBHOOK_URL', '') || env('ALERT_WEBHOOK_URL', '');
if (sandbox || !url) return [];

const format = env('ALERT_PAYLOAD_FORMAT', 'slack').toLowerCase();
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item) => {
  const j = item.json || {};
  const exec = j.execution || {};
  const wf = j.workflow || {};
  const err = exec.error || j.trigger?.error || {};
  const text = [
    `[DMARC] WORKFLOW ERROR | ${esc(wf.name || 'DMARC RUA parser')} | node: ${esc(exec.lastNodeExecuted || 'unknown')}`,
    `Error: ${esc(String(err.message || 'unknown error').slice(0, 400))}`,
    `Execution: ${esc(exec.url || exec.id || 'n/a')} (mode: ${esc(exec.mode || 'n/a')})`,
  ].join('\n');
  return { json: { url, payload: format === 'generic' ? { text, event_type: 'workflow_error', workflow: wf.name || null, execution_id: exec.id || null } : { text } } };
});
